INSERT INTO public.ui_translations (locale, translation_key, value) VALUES
('vi', 'pronlesson.ee2340b8-300b-41e7-830e-5501431b91be|explain', 'Chia câu dài thành các nhóm nghĩa ngắn với một khoảng dừng rất nhỏ giữa chúng. Nghe sẽ bình tĩnh và rõ ràng.'),
('vi', 'pronlesson.ee2340b8-300b-41e7-830e-5501431b91be|point|0', 'Dừng ở các dấu /.'),
('vi', 'pronlesson.ee2340b8-300b-41e7-830e-5501431b91be|point|1', 'Không bao giờ dừng ở giữa một nhóm nghĩa.'),
('vi', 'pronlesson.220fe380-b5ec-4bd4-a4ca-376052cfaaaf|explain', 'Trong câu trả lời hai phút, hãy lên kế hoạch chỗ lấy hơi. Lấy hơi ở cuối một nhóm, không bao giờ ở giữa một nhóm.'),
('vi', 'pronlesson.220fe380-b5ec-4bd4-a4ca-376052cfaaaf|point|0', 'Một hơi cho mỗi nhóm.'),
('vi', 'pronlesson.220fe380-b5ec-4bd4-a4ca-376052cfaaaf|point|1', 'Hạ giọng một chút ở cuối một nhóm đã hoàn thành.'),
('vi', 'pronlesson.f4ab8f1f-ada8-4960-b494-7a307e954a9a|explain', 'Chỉ đường dễ theo dõi hơn nhiều khi được chia thành các cụm nhỏ với khoảng dừng.'),
('vi', 'pronlesson.c2a32a8d-8213-489a-a6ad-c1a4dbbe658d|explain', 'Bài thuyết trình nghe tự tin hơn nhiều khi được chia nhóm rõ ràng, cho khán giả thời gian để tiếp nhận.'),
('vi', 'pronlesson.407a6ad5-4e80-4fbb-a5aa-58e30825238e|explain', 'Câu chuyện trôi chảy hơn và tạo được sự hồi hộp khi được chia nhóm ở những chỗ ngắt tự nhiên của lối kể.'),
('vi', 'pronlesson.a532594d-9141-4dae-b1cc-75fa7be4308e|explain', 'Với câu trả lời Part 2 hoặc Part 3, hãy chia từng lý do hỗ trợ riêng ra để giám khảo có thể theo dõi cấu trúc của bạn.'),
('vi', 'pronlesson.a98a4554-770c-4bb8-876c-06aa4c2faac3|explain', 'Một cụm mở đầu ngắn thường là một nhóm riêng, được ngăn cách bằng một khoảng dừng nhỏ.'),
('vi', 'pronlesson.12f7883d-32c7-4b75-a663-3d9d4bb9883d|explain', 'Các bước công thức nấu ăn tự nhiên chia thành nhóm ở mỗi hành động — dừng một chút giữa chúng.'),
('vi', 'pronlesson.108ad24b-b8bf-4e9d-aed3-fe05e5b618d0|explain', 'Câu so sánh chia nhóm quanh mỗi vế của sự so sánh, với một khoảng dừng nhỏ trước từ nối chỉ sự tương phản.'),
('vi', 'pronlesson.8856e3b1-10cf-4bbe-b86d-3f177236c45f|explain', 'Mô tả dữ liệu chia nhóm quanh mỗi xu hướng hoặc con số, cho người nghe thời gian để hình dung.'),
('vi', 'pronlesson.0012d622-27a7-4eea-acfb-586f3dabe33a|explain', 'Đọc to một email hoặc tin nhắn trang trọng vẫn cần chia nhóm tự nhiên, không phải đọc đều đều từng từ một.'),
('vi', 'pronlesson.a874e3c1-cd0f-44a1-8313-6e826f04c696|explain', 'Mệnh đề quan hệ (''which...'', ''who...'') thường là một nhóm riêng, được ngăn cách bằng những khoảng dừng nhỏ ở cả hai bên.'),
('vi', 'pronlesson.98c2a878-5b79-4fe5-8119-7d0405f482e4|explain', 'Hướng dẫn an toàn cần được chia nhóm thật rõ ràng để mỗi chỉ dẫn không thể nhầm lẫn.'),
('vi', 'pronlesson.ec3e3d8f-1b58-411f-9e3b-9ba2d8faf353|explain', 'Khi câu dài hơn, số nhóm cũng tăng lên — hãy luyện thêm từng nhóm một.'),
('vi', 'pronlesson.a68aee7f-dc45-41c2-b9ac-8ad2dece2a9d|explain', 'Câu trả lời phỏng vấn có cấu trúc chia nhóm quanh từng phần của câu chuyện: tình huống, hành động, kết quả.'),
('vi', 'pronlesson.b7bd1d41-68eb-4c84-9e6c-f13e058f8840|explain', 'Một lời bình chèn thêm vào giữa câu là một nhóm riêng, được ngăn cách rõ ràng ở cả hai bên.'),
('vi', 'pronlesson.46dcd798-4000-43b7-82c8-f1b850d44401|explain', 'Mỗi vế của cấu trúc này là một nhóm riêng, với một khoảng dừng nhỏ ngay trước ''but also''.'),
('vi', 'pronlesson.6872d745-0520-44ee-84d5-4e4aa20041d1|explain', 'Buổi giới thiệu sản phẩm chia nhóm quanh mỗi tính năng được trình bày, dừng lại để nó đọng lại trước khi chuyển sang phần tiếp theo.'),
('vi', 'pronlesson.70c5a6fd-f1ee-4e75-ba54-e59b91778c7c|explain', 'Giải thích quy tắc chia nhóm quanh từng quy tắc riêng để người nghe có thể theo dõi.'),
('vi', 'pronlesson.2ede03c2-32c0-4baa-a40d-646b4aa67aac|explain', 'Mệnh đề chỉ thời gian thường là một nhóm riêng, dù nó đứng ở đầu hay cuối câu.'),
('vi', 'pronlesson.ac944083-43e1-4cc4-a930-8fe3d7407989|explain', 'Một bài luyện xây dựng thứ hai, bắt đầu phức tạp hơn và thêm nhiều nhóm hơn nữa.'),
('vi', 'pronlesson.c23ace34-9c05-4582-84fd-51cbea29270c|explain', 'Câu nguyên nhân – kết quả chia nhóm riêng quanh nguyên nhân và kết quả dẫn đến.'),
('vi', 'pronlesson.820c8db1-5ce7-4345-afd0-21cb237b08ca|explain', 'Khi liệt kê nhiều ưu và nhược điểm trong một hơi, mỗi ý có một nhóm nhỏ riêng.'),
('vi', 'pronlesson.0ce9ae3d-452f-46a3-b6b1-8851c0f17eda|explain', 'Thông báo tại nơi làm việc cần chia nhóm rõ ràng để không ai bỏ lỡ chi tiết quan trọng.'),
('vi', 'pronlesson.a7964628-bb0f-4d5b-a2e6-25da36b845c1|explain', 'Khi truyền đạt tin khó, việc chia nhóm đặc biệt rõ ràng sẽ giúp ích, cho người nghe thời gian để tiếp nhận từng phần.'),
('vi', 'pronlesson.317029af-512a-4dd9-8ea9-9aad1d12e8d9|explain', 'Bài phát biểu tưởng niệm chia nhóm quanh mỗi ký ức hoặc phẩm chất được tôn vinh, với một khoảng dừng để nó đọng lại.'),
('vi', 'pronlesson.34c4f175-ba13-4677-9497-dc48c445fbb7|explain', 'Mô tả một hình ảnh được chia nhóm quanh từng yếu tố bạn nhận thấy, đi từ tổng quát đến cụ thể.'),
('vi', 'pronlesson.dc3e895d-2aa0-4bf9-b282-d5a5dcfb3089|explain', 'Giải thích lịch sử được chia nhóm quanh nguyên nhân, sự kiện và hậu quả.'),
('vi', 'pronlesson.e473781e-b42f-4776-ac8e-735dcf305862|explain', 'Tóm tắt cốt truyện được chia nhóm quanh mỗi bước ngoặt lớn trong câu chuyện.'),
('vi', 'pronlesson.d78438f2-4441-454a-81d0-7a05977dbea0|explain', 'Đàm phán được chia nhóm quanh đề nghị và điều kiện của bạn, tạo trọng lượng cho từng phần.'),
('vi', 'pronlesson.58dfbef4-9a1b-4439-9a84-5af4be18f38e|explain', 'Mô tả triệu chứng được chia nhóm quanh từng triệu chứng riêng biệt để không bỏ sót điều gì.'),
('vi', 'pronlesson.7f5e6a91-06ee-4c90-9f18-2b38835e0141|explain', 'Lịch trình được chia nhóm quanh mỗi ngày hoặc điểm đến.'),
('vi', 'pronlesson.8b8057f0-9883-4855-b7b0-fe957d2dadeb|explain', 'Giải thích ngân sách được chia nhóm quanh mỗi hạng mục chi tiêu.'),
('vi', 'pronlesson.e1dcd566-ff4c-42f2-b6fd-eaf1833a1cc4|explain', 'So sánh các lời đề nghị được chia nhóm quanh ưu điểm của từng công việc, với một khoảng dừng rõ ràng trước phần tương phản.'),
('vi', 'pronlesson.43c654d5-e2fc-400d-92a2-2dd58a9c3943|explain', 'Khắc phục sự cố được chia nhóm quanh mỗi điều bạn đã thử.'),
('vi', 'pronlesson.43c02b85-c13a-4da1-af76-6aea60bef08b|explain', 'Kể lại giấc mơ được chia nhóm quanh mỗi khoảnh khắc kỳ lạ hoặc đáng nhớ.'),
('vi', 'pronlesson.2b2e72bd-902a-4033-a162-2f6ff6a4b17b|explain', 'Thảo luận về các chủ đề môi trường được chia nhóm quanh vấn đề và hậu quả của nó, thường gặp trong IELTS Part 3.'),
('vi', 'pronlesson.1fc6a1a2-fb00-4b91-9104-943e6aed0cc2|explain', 'Mô tả thành phố được chia nhóm quanh mỗi đặc điểm bạn đề cập.'),
('vi', 'pronlesson.ee4d27a6-d974-4b92-be15-9c95f3c83f88|explain', 'Giải thích sở thích được chia nhóm quanh việc bạn làm gì, tại sao bạn thích nó và tần suất như thế nào.'),
('vi', 'pronlesson.58140aed-24bc-412a-8305-bcb0501e7e31|explain', 'Kể chuyện hoài niệm được chia nhóm quanh mỗi chi tiết được nhớ lại, thường gặp trong IELTS Part 2.'),
('vi', 'pronlesson.1096f29f-95c2-497c-9749-cf55eaabed8d|explain', 'Giải thích chính sách được chia nhóm quanh quy tắc và ngoại lệ hoặc lý do của nó.'),
('vi', 'pronlesson.cb65f5a0-a4a7-46c9-a330-9004f2e93507|explain', 'Nói về chiến lược học tập được chia nhóm quanh mỗi kỹ thuật được mô tả.'),
('vi', 'pronlesson.7eddd162-3752-4698-95b4-cf7c8e88e49b|explain', 'Giải thích công nghệ được chia nhóm quanh mỗi bước hoặc tính năng.'),
('vi', 'pronlesson.9ee8815e-0536-43dd-be67-e09603f44406|explain', 'Tóm tắt thể thao được chia nhóm quanh mỗi khoảnh khắc then chốt của trận đấu.'),
('vi', 'pronlesson.4875e7c1-da28-420b-accc-b7a7470f07ed|explain', 'Lời khuyên sức khỏe được chia nhóm quanh mỗi khuyến nghị.'),
('vi', 'pronlesson.3cfaf43c-cee0-426e-bd22-67293a9ba884|explain', 'Thảo luận về kiểu thời tiết được chia nhóm quanh nguyên nhân và kết quả điển hình.'),
('vi', 'pronlesson.999a826d-1bea-47c9-ae00-04403e053a41|explain', 'Cuộc gọi hỗ trợ được chia nhóm quanh mỗi bước khắc phục sự cố bạn yêu cầu khách hàng thử.'),
('vi', 'pronlesson.26c2e6cb-da98-4e5a-ad5e-7cf0605cc523|explain', 'Ngay cả văn bản trang trọng dày đặc cũng cần được chia nhóm rõ ràng khi đọc thành tiếng, nếu không sẽ không thể theo dõi được.'),
('vi', 'pronlesson.763ce319-a87b-4299-864e-79a3739c95b8|explain', 'Việc ra quyết định cá nhân được chia nhóm quanh mỗi yếu tố được cân nhắc, thường gặp trong thảo luận IELTS Part 3.'),
('vi', 'pronlesson.79819ee2-190a-4fed-9dd4-cb7e24d94ec0|explain', 'Phần kết thúc — hãy đánh dấu chỗ bạn sẽ dừng trước khi kiểm tra các nhóm được gợi ý.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|explain', 'Thành thạo chia nhóm qua 50 bài luyện tập có mục tiêu. Hãy nghe kỹ mẫu AI, lặp lại và ghi âm giọng nói của bạn để nhận điểm phát âm chi tiết theo thời gian thực và phản hồi.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|point|0', 'Tập trung vào nhịp điệu, trọng âm và dòng chảy được làm nổi bật trong mỗi bài luyện tập.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|point|1', 'Nghe âm thanh mẫu tham chiếu trước mỗi lần ghi âm.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|point|2', 'Xem lại điểm AI và phản hồi ở cấp độ âm vị để xác định chính xác các điểm cần cải thiện.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|caution', 'Đừng vội vàng làm qua các bài luyện tập; hãy ưu tiên sự rõ ràng, nhịp điệu tự nhiên và phát âm chính xác.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|0', 'Dừng giữa cụm giới từ chỉ thời gian và mệnh đề chính.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|1', 'Ngắt tự nhiên sau mệnh đề phụ chỉ điều kiện.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|2', 'Ngắt để tách cụm danh từ chủ ngữ dài khỏi vị ngữ.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|3', 'Ngắt sau mệnh đề phụ mở đầu.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|4', 'Ngắt để nhấn mạnh phần nhượng bộ trước kết quả.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|5', 'Ngắt sau cụm trích dẫn.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|6', 'Từ nối diễn ngôn được chia thành cụm riêng.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|7', 'Ba nhóm hơi thở cân đối.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|8', 'Mệnh đề chỉ mục đích theo sau là hành động mệnh lệnh.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|9', 'Ngắt đánh dấu sự chuyển tiếp thời gian.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|10', 'Mệnh đề quan hệ không xác định được bao quanh bằng các khoảng ngắt.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|11', 'Mệnh đề trong ngoặc được tách ở cả hai bên.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|12', 'Cụm từ trong ngoặc mang ý tương phản được tách riêng.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|13', 'Cụm động từ nguyên mẫu đồng vị được đặt trong các khoảng ngắt.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|14', 'Cụm miêu tả dạng phân từ.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|15', 'Bốn cụm tu từ cân đối.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|16', 'Chia cụm theo từng bước quy trình.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|17', 'Các liên từ tương quan tạo ra những khoảng ngắt nhịp nhàng.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|18', 'Cấu trúc song song đảo ngữ được chia gọn gàng.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|19', 'Ngắt giữa hai lựa chọn khẩn cấp.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|20', 'Diễn thuyết trước công chúng: cụm hô ngữ, cụm tri ân, cụm thời gian.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|21', 'Cách trình bày thuyết trình trang trọng.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|22', 'Cách diễn đạt hùng biện có chủ đích.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|23', 'Phép đối tu từ được chia thành ba đơn vị tư tưởng.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|24', 'Nhịp điệu truyền cảm hứng.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|25', 'Các cụm hành động tự sự.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|26', 'Cụm giới từ mang tính thi ca.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|27', 'Miêu tả không khí bằng ba nhịp rõ rệt.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|28', 'Cụm trạng từ mang cảm xúc.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|29', 'Nhịp điệu kể chuyện.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|30', 'Chia cụm trong liên hệ công việc.'),
('vi', 'pronlesson.36c7ad3a-bbc7-40a8-a000-7f316edba35e|note|31', 'Thông báo giao thông chính thức.'),
