('fr', 'pronlesson.32c7dc70-a486-4d9c-8fb8-e9696206713d|note|10', '''should have'' -> ''shoulda'' /ʃʊdə/.'),
('fr', 'pronlesson.32c7dc70-a486-4d9c-8fb8-e9696206713d|note|11', '''could have'' -> ''coulda'' /kʊdə/.'),
('fr', 'pronlesson.32c7dc70-a486-4d9c-8fb8-e9696206713d|note|12', '''would have'' -> ''woulda'' /wʊdə/.'),
('fr', 'pronlesson.32c7dc70-a486-4d9c-8fb8-e9696206713d|note|13', '''must have'' -> ''musta'' /mʌstə/.'),
('fr', 'pronlesson.32c7dc70-a486-4d9c-8fb8-e9696206713d|note|14', '''might have'' -> ''mighta'' /maɪtə/.'),
('fr', 'pronlesson.32c7dc70-a486-4d9c-8fb8-e9696206713d|note|15', '''used to'' -> ''usta'' /juːstə/.'),
('fr', 'pronlesson.32c7dc70-a486-4d9c-8fb8-e9696206713d|note|16', '''supposed to'' -> ''sposta'' /spoʊstə/.'),
