('sv', 'pronlesson.69aea060-6196-4732-a658-25a6b0d08e52|point|0', 'different → diff''rent'),
('sv', 'pronlesson.69aea060-6196-4732-a658-25a6b0d08e52|point|1', 'general → gen''ral'),
('sv', 'pronlesson.69aea060-6196-4732-a658-25a6b0d08e52|point|2', 'several → sev''ral'),
('sv', 'pronlesson.69aea060-6196-4732-a658-25a6b0d08e52|point|3', 'camera → cam''ra'),
