('he', 'pronlesson.32c7dc70-a486-4d9c-8fb8-e9696206713d|note|39', '''some'' -> /səm/; ''for'' -> /fər/.'),
('he', 'pronlesson.32c7dc70-a486-4d9c-8fb8-e9696206713d|note|40', '''for'' -> /fər/; ''you'' -> /jə/.'),
('he', 'pronlesson.32c7dc70-a486-4d9c-8fb8-e9696206713d|note|41', '''are'' -> /ər/; ''you'' -> /jə/; ''to'' -> /tə/.'),
('he', 'pronlesson.32c7dc70-a486-4d9c-8fb8-e9696206713d|note|42', '''were'' מצטמצמת ל-/wər/.'),
('he', 'pronlesson.32c7dc70-a486-4d9c-8fb8-e9696206713d|note|43', '''can'' -> /kən/; ''for'' -> /fər/; ''you'' -> /jə/.'),
('he', 'pronlesson.32c7dc70-a486-4d9c-8fb8-e9696206713d|note|44', '''as'' -> /əz/; ''can'' -> /kən/.'),
